// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // The recipient of withdraw is msg.sender, which must be owner (this test contract).
    // Receiving ETH here consumes/fails so the low-level send/transfer fails, making
    // the reference revert while the mutant silently ignores send's false result.
    receive() external payable { revert(); }

    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), amount);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok || address(c).balance == 0);
    }
}
